import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';

export interface StewardshipState {
    trustLevel: string;
    epoch: number;
    isSafeMode: boolean;
    activeDrill: string;
}

export interface EvidenceEntry {
    sequenceId: number;
    type: string;
    timestamp: number;
    payload: string;
    evidence: {
        hash: string;
        prevHash: string;
        signature: string;
        epoch: number;
        trustLevel: string;
        verdict: string;
    };
}

@Injectable({
    providedIn: 'root'
})
export class StewardshipService {
    private stateSubject = new BehaviorSubject<StewardshipState>({
        trustLevel: 'VERIFIED',
        epoch: 100,
        isSafeMode: false,
        activeDrill: 'NONE'
    });

    private evidenceSubject = new BehaviorSubject<EvidenceEntry[]>([]);

    state$ = this.stateSubject.asObservable();
    evidence$ = this.evidenceSubject.asObservable();

    private baselineFixtures: EvidenceEntry[] = [
        {
            sequenceId: 1000,
            type: 'GOVERNANCE_INIT',
            timestamp: 1715856000000,
            payload: 'Epoch 100 Initialized',
            evidence: {
                hash: '0x1000',
                prevHash: '0x0000',
                signature: 'sig|100|1000|INIT',
                epoch: 100,
                trustLevel: 'FULL',
                verdict: 'VERIFIED'
            }
        },
        {
            sequenceId: 1001,
            type: 'IDENTITY_REGISTRATION',
            timestamp: 1715856060000,
            payload: 'Node A registered',
            evidence: {
                hash: '0x1001',
                prevHash: '0x1000',
                signature: 'sig|100|1001|NODE_A',
                epoch: 100,
                trustLevel: 'FULL',
                verdict: 'VERIFIED'
            }
        },
        {
            sequenceId: 1002,
            type: 'POLICY_ENFORCEMENT',
            timestamp: 1715856120000,
            payload: 'Inbound Traffic Rule Applied',
            evidence: {
                hash: '0x1002',
                prevHash: '0x1001',
                signature: 'sig|100|1002|POLICY',
                epoch: 100,
                trustLevel: 'FULL',
                verdict: 'VERIFIED'
            }
        }
    ];

    constructor() {
        this.loadBaseline();
    }

    private loadBaseline() {
        this.evidenceSubject.next([]);
        this.baselineFixtures.forEach((entry, i) => {
            setTimeout(() => {
                const current = this.evidenceSubject.value;
                this.evidenceSubject.next([...current, entry]);
            }, i * 800);
        });
    }

    triggerDrill(drillId: string) {
        this.stateSubject.next({
            ...this.stateSubject.value,
            activeDrill: drillId
        });

        switch (drillId) {
            case 'IFD-001': // Replay Determinism
                this.loadBaseline();
                break;
            case 'IFD-002': // Cognitive Degradation
                this.injectEvidence({
                    sequenceId: 1003,
                    type: 'AUTH_DEGRADATION',
                    timestamp: Date.now(),
                    payload: 'Signer node-c revoked by governance.',
                    evidence: {
                        hash: '0x1003',
                        prevHash: '0x1002',
                        signature: 'sig|100|1003|REVOKE',
                        epoch: 100,
                        trustLevel: 'DEGRADED',
                        verdict: 'DEGRADED'
                    }
                });
                this.stateSubject.next({ ...this.stateSubject.value, trustLevel: 'DEGRADED' });
                break;
            case 'IFD-003': // Governance convergence (Safe Mode)
                this.stateSubject.next({ ...this.stateSubject.value, trustLevel: 'DEGRADED', isSafeMode: true });
                break;
            case 'IFD-004': // Adversarial
                this.injectEvidence({
                    sequenceId: 1004,
                    type: 'REPLAY_POISONING',
                    timestamp: Date.now(),
                    payload: 'CRITICAL: Causal rewrite attempt detected.',
                    evidence: {
                        hash: '0xPOISON',
                        prevHash: '0xFAKE',
                        signature: 'sig|100|1004|FORGED',
                        epoch: 100,
                        trustLevel: 'UNTRUSTED',
                        verdict: 'UNTRUSTED'
                    }
                });
                this.stateSubject.next({ ...this.stateSubject.value, trustLevel: 'UNTRUSTED', isSafeMode: true });
                break;
        }
    }

    private injectEvidence(entry: EvidenceEntry) {
        const current = this.evidenceSubject.value;
        this.evidenceSubject.next([...current, entry]);
    }
}
